      {mark === 'ring' ? <path d={ringPath(0, 0, half + size * 0.62, size * 0.98, { seed, start: Math.PI * 0.84, wobble: 0.03 })} {...stroke} {...drawn} /> : null}
      {mark === 'dashed' ? (
